using System;
class DeathWardChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var ward=new DeathWardEffect();var combat=new CombatState();long now=0;combat.DeathWardGuard=p=>ward.Consume(p,now);ward.Cast(true,now);combat.GrantPlayerTemporaryHp(10);combat.ApplyPlayerDamage(9);Check(ward.Active(true,now)&&combat.PlayerHp==10,"absorbed hit does not spend ward");combat.ApplyPlayerDamage(1000,true);Check(combat.PlayerHp==1&&!combat.PlayerDead&&!ward.Active(true,now),"lethal massive damage replaced with one hp");combat.ApplyPlayerDamage(1);Check(combat.PlayerHp==0&&!combat.PlayerDead,"second damage knocks down normally");combat.ResetBattle();ward.Cast(true,now);combat.GrantPlayerTemporaryHp(7);combat.KillPlayer();Check(combat.PlayerHp==10&&!combat.PlayerDead&&combat.PlayerTemporaryHp==7&&!ward.Active(true,now),"instant death negated without changing hp or temporary hp");combat.KillPlayer();Check(combat.PlayerDead,"second instant kill works");combat.ResetBattle();ward.Cast(false,now);combat.ApplyDamage(1000);Check(combat.Hp==1&&!ward.Active(false,now),"monster lethal damage guarded");ward.Cast(false,now);combat.GrantMonsterTemporaryHp(4);combat.KillMonster();Check(combat.Hp==1&&combat.MonsterTemporaryHp==4,"monster instant death guarded");combat.KillMonster();Check(combat.Hp==0,"monster second kill");combat.ResetBattle();ward.Cast(true,now);combat.SetAidBonus(true,5);combat.ApplyPlayerDamage(10);Check(combat.PlayerHp==5&&ward.Active(true,now),"aid expiration fixture");combat.SetAidBonus(true,0);Check(combat.PlayerHp==1&&!ward.Active(true,now),"2024 ward also prevents aid expiry dropping hp to zero");combat.ResetBattle();ward.Cast(false,now);combat.SetAidBonus(false,5);combat.ApplyDamage(1000);combat.SetAidBonus(false,0);Check(combat.Hp==1&&!ward.Active(false,now),"monster aid expiry also guarded");ward.Clear();combat.ResetBattle();ward.Cast(true,0);now=4800;combat.ApplyPlayerDamage(10);Check(combat.PlayerHp==0&&!ward.Active(true,now),"eight hour expiry");combat.ResetBattle();ward.Clear();combat.ApplyPlayerDamage(10);ward.Cast(true,now);combat.ResolveDeathSave(1);combat.ResolveDeathSave(1);Check(combat.PlayerDead&&ward.Active(true,now),"ward does not replace death save failures");ward.Clear();Check(!ward.Active(true,now),"clear");Console.WriteLine("PASS: death ward lethal and massive damage, temp hp, instant kills, expiry, aid expiry and death saves");}
}
